public void update(String entry, String value, boolean debug) throws Exception {

        this.requestLock.lock();
        try {

            SwitchDomain tempSwitchDomain = this.switchDomain.clone();

            if (entry.equals(SwitchEntry.DISTRO_THRESHOLD)) {
                float threshold = Float.parseFloat(value);  //UNCOVERED
                if (threshold <= 0) {  //UNCOVERED
                    throw new IllegalArgumentException("distroThreshold can not be zero or negative: " + threshold);  //UNCOVERED
                }
                tempSwitchDomain.setDistroThreshold(threshold);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.CLIENT_BEAT_INTERVAL)) {
                long clientBeatInterval = Long.parseLong(value);  //UNCOVERED
                tempSwitchDomain.setClientBeatInterval(clientBeatInterval);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.PUSH_VERSION)) {

                String[] parts = value.split(":");
                if (parts.length < 2) {
                    throw new IllegalArgumentException(
                            "illegal format, must be 'type:version', but got: " + value);
                }
                String type = parts[0];
                String version = parts[1];

                if (!version.matches(UtilsAndCommons.VERSION_STRING_SYNTAX)) {
                    throw new IllegalArgumentException(
                            "illegal version, must match: " + UtilsAndCommons.VERSION_STRING_SYNTAX);
                }

                if (StringUtils.equals(SwitchEntry.CLIENT_JAVA, type)) {
                    tempSwitchDomain.setPushJavaVersion(version);
                } else if (StringUtils.equals(SwitchEntry.CLIENT_PYTHON, type)) {
                    tempSwitchDomain.setPushPythonVersion(version);
                } else if (StringUtils.equals(SwitchEntry.CLIENT_C, type)) {
                    tempSwitchDomain.setPushCVersion(version);  //UNCOVERED
                } else if (StringUtils.equals(SwitchEntry.CLIENT_GO, type)) {
                    tempSwitchDomain.setPushGoVersion(version);  //UNCOVERED
                } else if (StringUtils.equals(SwitchEntry.CLIENT_CSHARP, type)) {
                    tempSwitchDomain.setPushCSharpVersion(version);  //UNCOVERED
                } else {
                    throw new IllegalArgumentException("unsupported client type: " + type);
                }
            }

            if (entry.equals(SwitchEntry.PUSH_CACHE_MILLIS)) {
                long cacheMillis = Long.parseLong(value);  //UNCOVERED

                if (cacheMillis < SwitchEntry.MIN_PUSH_CACHE_TIME_MIILIS) {  //UNCOVERED
                    throw new IllegalArgumentException("min cache time for http or tcp is too small(<10000)");  //UNCOVERED
                }

                tempSwitchDomain.setDefaultPushCacheMillis(cacheMillis);  //UNCOVERED
            }

            // extremely careful while modifying this, cause it will affect all clients without pushing enabled
            if (entry.equals(SwitchEntry.DEFAULT_CACHE_MILLIS)) {
                long cacheMillis = Long.parseLong(value);  //UNCOVERED

                if (cacheMillis < SwitchEntry.MIN_CACHE_TIME_MIILIS) {  //UNCOVERED
                    throw new IllegalArgumentException("min default cache time  is too small(<1000)");  //UNCOVERED
                }

                tempSwitchDomain.setDefaultCacheMillis(cacheMillis);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.MASTERS)) {
                List<String> masters = Arrays.asList(value.split(","));  //UNCOVERED
                tempSwitchDomain.setMasters(masters);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.DISTRO)) {
                boolean enabled = Boolean.parseBoolean(value);  //UNCOVERED
                tempSwitchDomain.setDistroEnabled(enabled);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.CHECK) || entry.equals(SwitchEntry.HEALTH_CHECK_ENABLED)) {
                boolean enabled = Boolean.parseBoolean(value);  //UNCOVERED
                tempSwitchDomain.setHealthCheckEnabled(enabled);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.PUSH_ENABLED)) {
                boolean enabled = Boolean.parseBoolean(value);  //UNCOVERED
                tempSwitchDomain.setPushEnabled(enabled);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.SERVICE_STATUS_SYNC_PERIOD)) {
                long millis = Long.parseLong(value);  //UNCOVERED

                if (millis < SwitchEntry.MIN_SERVICE_SYNC_TIME_MIILIS) {  //UNCOVERED
                    throw new IllegalArgumentException("serviceStatusSynchronizationPeriodMillis is too small(<5000)");  //UNCOVERED
                }

                tempSwitchDomain.setServiceStatusSynchronizationPeriodMillis(millis);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.SERVER_STATUS_SYNC_PERIOD)) {
                long millis = Long.parseLong(value);  //UNCOVERED

                if (millis < SwitchEntry.MIN_SERVER_SYNC_TIME_MIILIS) {  //UNCOVERED
                    throw new IllegalArgumentException("serverStatusSynchronizationPeriodMillis is too small(<15000)");  //UNCOVERED
                }

                tempSwitchDomain.setServerStatusSynchronizationPeriodMillis(millis);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.HEALTH_CHECK_TIMES)) {
                int times = Integer.parseInt(value);  //UNCOVERED

                tempSwitchDomain.setCheckTimes(times);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.DISABLE_ADD_IP)) {
                boolean disableAddIp = Boolean.parseBoolean(value);  //UNCOVERED

                tempSwitchDomain.setDisableAddIP(disableAddIp);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.SEND_BEAT_ONLY)) {
                boolean sendBeatOnly = Boolean.parseBoolean(value);  //UNCOVERED

                tempSwitchDomain.setSendBeatOnly(sendBeatOnly);  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.LIMITED_URL_MAP)) {
                Map<String, Integer> limitedUrlMap = new HashMap<>(16);  //UNCOVERED

                if (!StringUtils.isEmpty(value)) {  //UNCOVERED
                    String[] entries = value.split(",");  //UNCOVERED
                    for (String each : entries) {  //UNCOVERED
                        String[] parts = each.split(":");  //UNCOVERED
                        if (parts.length < 2) {  //UNCOVERED
                            throw new IllegalArgumentException("invalid input for limited urls");  //UNCOVERED
                        }

                        String limitedUrl = parts[0];  //UNCOVERED
                        if (StringUtils.isEmpty(limitedUrl)) {  //UNCOVERED
                            throw new IllegalArgumentException("url can not be empty, url: " + limitedUrl);  //UNCOVERED
                        }

                        int statusCode = Integer.parseInt(parts[1]);  //UNCOVERED
                        if (statusCode <= 0) {  //UNCOVERED
                            throw new IllegalArgumentException("illegal normal status code: " + statusCode);  //UNCOVERED
                        }

                        limitedUrlMap.put(limitedUrl, statusCode);  //UNCOVERED

                    }

                    tempSwitchDomain.setLimitedUrlMap(limitedUrlMap);  //UNCOVERED
                }
            }

            if (entry.equals(SwitchEntry.ENABLE_STANDALONE)) {

