            }

            if (entry.equals(SwitchEntry.DISTRO_SERVER_EXPIRED_MILLIS)) {
                tempSwitchDomain.setDistroServerExpiredMillis(Long.parseLong(value));  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.LIGHT_BEAT_ENABLED)) {
                tempSwitchDomain.setLightBeatEnabled(ConvertUtils.toBoolean(value));  //UNCOVERED
            }

            if (entry.equals(SwitchEntry.AUTO_CHANGE_HEALTH_CHECK_ENABLED)) {
                tempSwitchDomain.setAutoChangeHealthCheckEnabled(ConvertUtils.toBoolean(value));  //UNCOVERED
            }

            try {
                if (SwitchEntry.HTTP_HEALTH_PARAMS.equals(entry)) {
                    SwitchDomain.HttpHealthParams httpHealthParams = JacksonUtils.toObj(value, SwitchDomain.HttpHealthParams.class);  //UNCOVERED
                    tempSwitchDomain.setHttpHealthParams(httpHealthParams);  //UNCOVERED
                    validateHealthParams(httpHealthParams);  //UNCOVERED
                }
                if (SwitchEntry.TCP_HEALTH_PARAMS.equals(entry)) {
                    SwitchDomain.TcpHealthParams tcpHealthParams = JacksonUtils.toObj(value, SwitchDomain.TcpHealthParams.class);  //UNCOVERED
                    tempSwitchDomain.setTcpHealthParams(tcpHealthParams);  //UNCOVERED
                    validateHealthParams(tcpHealthParams);  //UNCOVERED
                }
                if (SwitchEntry.MYSQL_HEALTH_PARAMS.equals(entry)) {
                    tempSwitchDomain.setMysqlHealthParams(JacksonUtils.toObj(value, SwitchDomain.MysqlHealthParams.class));  //UNCOVERED
                }
            } catch (NacosDeserializationException e) {  //UNCOVERED
                throw new IllegalArgumentException("json param invalid.");  //UNCOVERED
            }

            if (debug) {
                update(tempSwitchDomain);
            } else {
                updateWithConsistency(tempSwitchDomain);  //UNCOVERED
            }

        } finally {
