@Override
    public String registerSkill(Skill skill, String namespaceId) throws NacosException {
        try {
            // 1. Validate skill name (only allow English letters, underscore, hyphen)
            if (StringUtils.isBlank(skill.getName())) {
                throw new NacosApiException(NacosException.INVALID_PARAM, ErrorCode.PARAMETER_MISSING,
                        "Skill name is required");
            }
            if (!skill.getName().matches(SKILL_NAME_PATTERN)) {
                throw new NacosApiException(NacosException.INVALID_PARAM, ErrorCode.PARAMETER_MISSING,
                        "Skill name can only contain English letters, underscore, and hyphen");
            }

            // 2. Build main config (skill.json)
            SkillUtils.ConfigInfo mainConfigInfo = SkillUtils.buildSkillMainConfigInfo(skill.getName());
            long uniformId = System.currentTimeMillis();
            ConfigForm mainConfigForm = buildMainConfigForm(skill, namespaceId, mainConfigInfo.getGroup(), uniformId);
            ConfigRequestInfo mainConfigRequest = new ConfigRequestInfo();
            Boolean mainPublishResult = configOperationService.publishConfig(mainConfigForm, mainConfigRequest, null);
            if (mainPublishResult == null || !mainPublishResult) {
                throw new NacosApiException(NacosException.SERVER_ERROR, ErrorCode.SERVER_ERROR,
                        String.format("Failed to publish main config for skill: %s", skill.getName()));
            }

            // 3. Build and publish resource configs
            if (skill.getResource() != null && !skill.getResource().isEmpty()) {  //UNCOVERED
                for (Map.Entry<String, SkillResource> entry : skill.getResource().entrySet()) {  //UNCOVERED
                    SkillResource resource = entry.getValue();  //UNCOVERED
                    SkillUtils.ConfigInfo resourceConfigInfo = SkillUtils.buildSkillResourceConfigInfo(  //UNCOVERED
                            skill.getName(), resource.getType(), resource.getName());  //UNCOVERED

                     ConfigForm resourceConfigForm = buildResourceConfigForm(resource, namespaceId,  //UNCOVERED
                            resourceConfigInfo.getGroup(), resourceConfigInfo.getDataId(), uniformId);  //UNCOVERED
                    ConfigRequestInfo resourceConfigRequest = new ConfigRequestInfo();  //UNCOVERED
                    Boolean resourcePublishResult = configOperationService.publishConfig(resourceConfigForm, resourceConfigRequest, null);  //UNCOVERED
                    if (resourcePublishResult == null || !resourcePublishResult) {  //UNCOVERED
                        throw new NacosApiException(NacosException.SERVER_ERROR, ErrorCode.SERVER_ERROR,  //UNCOVERED
                                 String.format("Failed to publish resource config for skill: %s, resource: %s",  //UNCOVERED
                                        skill.getName(), resource.getName()));  //UNCOVERED
                    }
                }  //UNCOVERED
            }

            long startOperationTime = System.currentTimeMillis();  //UNCOVERED
            syncEffectService.toSync(mainConfigForm, startOperationTime);  //UNCOVERED

            return skill.getName();  //UNCOVERED
        } catch (ConfigAlreadyExistsException e) {
            throw new NacosApiException(NacosException.CONFLICT, ErrorCode.RESOURCE_CONFLICT,
                    String.format("Skill name %s already exists", skill.getName()));
        }
    }

