@Override
    public Skill getSkillDetail(String namespaceId, String skillName) throws NacosException {
        // 1. Query main config
        SkillUtils.ConfigInfo mainConfigInfo = SkillUtils.buildSkillMainConfigInfo(skillName);
        ConfigQueryChainRequest request = ConfigQueryChainRequest.buildConfigQueryChainRequest(
                mainConfigInfo.getDataId(), mainConfigInfo.getGroup(), namespaceId);
        ConfigQueryChainResponse response = configQueryChainService.handle(request);

        if (response.getStatus() == ConfigQueryChainResponse.ConfigQueryStatus.CONFIG_NOT_FOUND) {
            throw new NacosApiException(NacosException.NOT_FOUND, ErrorCode.RESOURCE_NOT_FOUND,
                    "Skill not found: " + skillName);
        }

        // 2. Parse main config
        SkillMainConfig mainConfig = JacksonUtils.toObj(response.getContent(), SkillMainConfig.class);

        // 3. Build Skill object
        Skill skill = new Skill();
        skill.setNamespaceId(namespaceId);
        skill.setName(mainConfig.getName());
        skill.setDescription(mainConfig.getDescription());
        skill.setInstruction(mainConfig.getInstruction());

        // 4. Query all resource configs
        Map<String, SkillResource> resourceMap = new HashMap<>(
                mainConfig.getResources() != null ? mainConfig.getResources().size() : 16);
        if (mainConfig.getResources() != null && !mainConfig.getResources().isEmpty()) {
            for (SkillResourceRef resourceRef : mainConfig.getResources()) {  //UNCOVERED
                // Generate resourceId from type and name
                String resourceId = SkillUtils.generateResourceId(resourceRef.getType(), resourceRef.getName());  //UNCOVERED

                // Query resource config using resourceRef info
                SkillUtils.ConfigInfo resourceConfigInfo = SkillUtils.buildSkillResourceConfigInfo(  //UNCOVERED
                        skillName, resourceRef.getType(), resourceRef.getName());  //UNCOVERED
                ConfigQueryChainRequest resourceRequest = ConfigQueryChainRequest.buildConfigQueryChainRequest(  //UNCOVERED
                        resourceConfigInfo.getDataId(), resourceConfigInfo.getGroup(), namespaceId);  //UNCOVERED
                ConfigQueryChainResponse resourceResponse = configQueryChainService.handle(resourceRequest);  //UNCOVERED

                if (resourceResponse.getStatus() == ConfigQueryChainResponse.ConfigQueryStatus.CONFIG_FOUND_FORMAL  //UNCOVERED
                        || resourceResponse.getStatus() == ConfigQueryChainResponse.ConfigQueryStatus.CONFIG_FOUND_GRAY) {  //UNCOVERED
                    SkillResource resource = JacksonUtils.toObj(resourceResponse.getContent(), SkillResource.class);  //UNCOVERED
                    // Use resourceId as key so multi-level paths and same filename in different folders are unique
                    resourceMap.put(resourceId, resource);  //UNCOVERED
                } else {  //UNCOVERED
                     LOGGER.warn("Resource configuration not found: dataId={}, group={}",  //UNCOVERED
                            resourceConfigInfo.getDataId(), resourceConfigInfo.getGroup());  //UNCOVERED
                }
            }  //UNCOVERED
        }
        skill.setResource(resourceMap);

        return skill;
    }

